function reachableLine(x1,z1,x2,z2){const distance=Math.hypot(x2-x1,z2-z1),steps=Math.ceil(distance/.16);for(let i=1;i<=steps;i++)if(!canMove(x1+(x2-x1)*i/steps,z1+(z2-z1)*i/steps))return false;return true}
const navCells=new Map(),navEdges=new Map();let navVersion='';function navCell(a,b){const key=a+','+b;if(!navCells.has(key))navCells.set(key,canMove(a*.5,b*.5));return navCells.get(key)}
