function setNpcDestination(p,x,z){const same=p.destination&&Math.hypot(x-p.destination.x,z-p.destination.z)<.4;if(same&&(p.route.length||npcElapsed<(p.nextPathAt||0)))return;p.destination={x,z};p.route=npcRoute(p.x,p.z,x,z);p.nextPathAt=npcElapsed+1.2;p.stuck=0}
