function openOverlay(id){if(campaignState?.paused||!campaignState?.started)return;modalOpen=true;keysDown.clear();document.exitPointerLock?.();document.querySelector('#'+id).classList.add('show');if(id==='mapOverlay')drawDiscoveryMap()}
function closeOverlay(id){document.querySelector('#'+id).classList.remove('show');modalOpen=false}
function menu(name){if(modalOpen)return;keysDown.clear();document.exitPointerLock?.();campaign?.menu(name)}
function handleKey(e){if(e.repeat)return;const k=e.key.toLowerCase();const menus={p:'perso',r:'rumeurs',u:'rumeurs',l:'relations',v:'services'};if(menus[k]){e.preventDefault();menu(menus[k]);return}if(k==='m'){e.preventDefault();modalOpen?closeOverlay('mapOverlay'):openOverlay('mapOverlay');return}if(e.key==='Escape'){document.exitPointerLock?.();if(modalOpen){for(const o of document.querySelectorAll('.overlay.show'))closeOverlay(o.id)}else campaign?.close();keysDown.clear();return}if(modalOpen||campaignState?.paused)return;if(k==='e'){const d=nearDoor();if(d)toggleDoor(d)}if(k==='f'){if(!searchLocker())interact()}if(k==='e')toggleUpperFloor()}
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['z','q','s','d','w','a','arrowup','arrowleft','arrowdown','arrowright','shift'].includes(k)&&!modalOpen&&!campaignState?.paused){keysDown.add(k);e.preventDefault()}handleKey(e)});document.addEventListener('keyup',e=>keysDown.delete(e.key.toLowerCase()));addEventListener('blur',()=>keysDown.clear());
renderer.domElement.addEventListener('click',()=>{if(!modalOpen&&!campaignState?.paused){renderer.domElement.requestPointerLock?.()}});
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===renderer.domElement;if(!locked)keysDown.clear()});document.addEventListener('mousemove',e=>{if(!locked||modalOpen||campaignState?.paused)return;yaw-=e.movementX*.0022;pitch-=e.movementY*.0018;pitch=Math.max(-1.1,Math.min(1.1,pitch));camera.rotation.set(pitch,yaw,0)});
